H=Path(__file__).resolve().parent;ap=argparse.ArgumentParser();ap.add_argument('--analysis',type=Path,default=H.parent/'analysis');a=ap.parse_args();D=a.analysis
files=['run_receipt.json','system_analysis_features.parquet','model_metrics.csv','coefficient_intervals.csv','system_predictions.parquet','grouped_cv_folds.csv','common_sample_membership.parquet'];hashes={str(D/f):hashlib.sha256((D/f).read_bytes()).hexdigest() for f in files};r=json.loads((D/'run_receipt.json').read_text())
