 for fl in np.unique(fold):
  train=fold!=fl;test=~train;ck(tag+f':fold{fl}:no_region_leak',set(groups[train]).isdisjoint(set(groups[test])));mu=x[train].mean(axis=0);ss=x[train].std(axis=0);ss[ss<=1e-12]=1.;XX=addconstant((x[train]-mu)/ss);Xt=addconstant((x[test]-mu)/ss);oo[test]=Xt@linalg.lstsq(XX,y[train],lapack_driver='gelsy')[0];null[test]=y[train].mean()
